              '07.6': { type: 'points', points: ['[Al(H₂O)₆]³⁺'], guidance: '1 mark (AO3).' },
              '07.7': { type: 'points', points: ['A circle around one or more N', 'A circle around one or more O⁻'], guidance: '2 marks (AO1 ×2).' },
              '07.8': { type: 'points', points: ['M1 n (EDTA⁴⁻) added = 5 x 10⁻ ⁴ mol', 'M2 n (Zn²⁺) = 1.89 x 10⁻ ⁴ mol', 'M3 n (EDTA⁴⁻) reacted with the 25 cm³ sample of Al³⁺ = 5 x 10⁻ ⁴ – 1.89 x 10⁻ ⁴ = 3.11 x 10⁻ ⁴ mol', 'M4 n EDTA⁴⁻ reacted with the 250 cm³ sample of Al³⁺ = 3.11 x 10⁻ ⁴ x 10 = 3.11 x 10⁻ ³ mol', 'M5 n Al₂(SO₄)₃xH₂O = 3.11 x 10⁻ ³ ÷ 2 = 1.555 x10⁻ ³ mol', 'M6 Mr Al₂(SO₄)₃xH₂O = 1.036 ÷ 1.555 x10⁻ ³= 666.2', 'M7 342.3 + 18 x = 666(.2) so x = 18'], guidance: '7 marks (AO2 ×7). alternative methods will be allowed M3 = M1 – M2 M4 = (M3 × 250)/(25) M5 = M4 ÷ 2 M6 = 1.036 ÷ M5 M7 = (M6 – 342.3)/(18) and answer as integer' },
              '08.1': { type: 'points', points: ['O₂ + 4 H⁺+ 4 e⁻ → 2 H₂O'], guidance: '1 mark (AO1).' },
              '08.2': { type: 'points', points: ['CH₃OH + H₂O → CO₂ + 6 H⁺+ 6 e⁻'], guidance: '1 mark (AO2).' },
