              '08.3': { type: 'points', points: ['2Ag + ZnO → Zn + Ag₂O'], guidance: '1 mark (AO3). ignore state symbols' },
              '08.4': { type: 'points', points: ['O₂(g) + 2H₂O(l) + 4e⁻ → 4OH⁻(aq)', 'Eo = (+)0.4(0) (V)'], guidance: '2 marks (AO1; AO2). ignore state symbols allow multiples' },
