              '12': { type: 'exact', points: ['A'], guidance: 'Correct answer is A: Electrons travel in the external circuit from zinc to lead.' },
              '13': { type: 'exact', points: ['A'], guidance: 'Correct answer is A: CH3COO–.' },
              '14': { type: 'exact', points: ['B'], guidance: 'Correct answer is B: 1.40.' },
