              '17': { type: 'exact', points: ['D'], guidance: 'Correct answer is D: The second ionisation energy of rubidium is lower than the second ionisation energy of lithium.' },
              '18': { type: 'exact', points: ['D'], guidance: 'Correct answer is D: To prevent the precipitation of other silver compounds.' },
              '19': { type: 'exact', points: ['D'], guidance: 'Correct answer is D: FeCl3(aq) and concentrated HCl(aq).' },
              '20': { type: 'exact', points: ['B'], guidance: 'Correct answer is B: ligand substitution.' },
              '21': { type: 'exact', points: ['C'], guidance: 'Correct answer is C: 1.0.' },
              '22': { type: 'exact', points: ['C'], guidance: 'Correct answer is C: Free-radical substitution.' },
              '23': { type: 'exact', points: ['B'], guidance: 'Correct answer is B: CH3CH2NH2.' },
              '24': { type: 'exact', points: ['A'], guidance: 'Correct answer is A: They are easily oxidised to carboxylic acids by acidified K2Cr2O7 solution.' },
              '25': { type: 'exact', points: ['B'], guidance: 'Correct answer is B: methyl propanoate.' },
