              '28': { type: 'exact', points: ['C'], guidance: 'Correct answer is C: Poly(propene).' },
              '29': { type: 'exact', points: ['D'], guidance: 'Correct answer is D.' },
              '30': { type: 'exact', points: ['B'], guidance: 'Correct answer is B: hydrolysis.' },
              '31': { type: 'exact', points: ['B'], guidance: 'Correct answer is B: CH3COOCH3 and NaOH(aq).' },
              '32': { type: 'exact', points: ['B'], guidance: 'Correct answer is B: hydrogen bonds.' },
